export const samplePayments=[['transaction_id','order_id','amount','status','fee','refund_amount','date','currency'],...sampleOrders.slice(1).filter(r=>r[0]!=='ORD-1043').map((r,i)=>[`pay_${String(8101+i)}`,r[0],r[0]==='ORD-1045'?'3000':r[1],r[0]==='ORD-1048'?'pending':'captured',r[0]==='ORD-1048'?'0':(Number(r[1])*.02).toFixed(2),r[0]==='ORD-1046'?'200':r[4],r[3],'INR']),['pay_8120','ORD-1099','1299','captured','25.98','0','2026-09-12','INR']];
export function getDemo(){const load=(rows,kind)=>{const parsed=parseCSV(toCSV(rows));return normalizeReport(parsed,kind,suggestMapping(parsed.headers,kind));};return {orders:load(sampleOrders,'orders'),payments:load(samplePayments,'payments')};}
